// `/claim` against the PHP that prints it (plan §5 S1.2b): `AuthViews::claim()`, captured once.
//
// The oracle is `test/fixtures/php-claim.json`, generated by `v4/scripts/gen-claim-fixture.sh` from the
// real `modules/Auth/Views/AuthViews.php` with a `Page` stub — not by booting the app (that needs PHP
// with `intl` and `pdo_sqlite`, which is why `php-html.json` is a bigger toolchain and this page is
// not in it). The shell is not compared here: `page.ts` is pinned by the login golden test, and the
// stub's `start()`/`end()` print nothing.
//
// Byte identity is the point, as it is for the login page: the comparison catches a changed space run,
// a reordered attribute or a missing `required`, and the second case pins `Page::e()`'s escaping in a
// value the form prints (the user name).

import { describe, expect, it } from "vitest";
import { claimPage } from "../../src/html/views";
import fixture from "../fixtures/php-claim.json";
import { TEST_PAGE } from "../helpers/page";

/** The `<main>` fragment: everything the fixture captured. */
const span = (html: string): string => {
	const start = html.indexOf("<main");
	const end = html.indexOf("</main>");
	return html.slice(start, end + "</main>".length);
};

/** The stub's brand logo is a marker; the real one is `page.ts`'s, pinned by the login golden test. */
const logo = (html: string): string => html.replace(/<img class="brand-logo"[^>]*>/g, "<IMG>");

/** The token the generator's stub `csrf()` returns, so no normalisation is needed on either side. */
const settings = { ...TEST_PAGE, csrf: fixture.pages.claim.csrf };

describe("/claim is the page v3 renders", () => {
	it("prints the form PHP prints, byte for byte", () => {
		expect(logo(span(claimPage(settings, { error: null, username: "" })))).toBe(fixture.pages.claim.body);
	});

	it("prints the error state, with the name escaped as Page::e() escapes it", () => {
		const html = claimPage(settings, {
			error: "This claim link is not valid. Ask for a new one.",
			username: "own<er> \"q\" 'z'",
		});
		expect(logo(span(html))).toBe(fixture.pages.claim.errorBody);
	});

	it("wraps it in the page shell, with the title and classes the PHP view asks for", () => {
		const html = claimPage(settings, { error: null, username: "" });
		expect(html).toContain("<title>Set up your Apotheke \u00b7 Apotheke</title>");
		expect(html).toContain('<body class="page-login page-claim">');
	});
});
